"""Public procurement experience: static HTML with browser-side enhancements."""
from html import escape
from company import digital_services

def enhance(pages, base, origin, icon, eye, btn, pagehero, cta):
    def photo(name, alt, cls=''):
        return f'<img class="{cls}" src="{base}assets/photos/{name}.jpg" width="1100" height="730" loading="lazy" decoding="async" alt="{alt}">'
    def add(item, label='Add to enquiry'):
        return f'<button class="btn light add-equipment" type="button" data-add="{item}">{label} <span aria-hidden="true">+</span></button>'
    explorer=f'''<section class="explorer-section" id="equipment-explorer"><div class="wrap">
      <div class="section-head"><div>{eye('Explore the equipment')}<h2>Get closer to your next setup.</h2></div><p>Select a device to understand where it fits. Add equipment to your enquiry, then discuss the specifications with us.</p></div>
      <div class="explorer-layout"><div class="equipment-tabs" role="tablist" aria-label="Equipment explorer">
      <button id="tab-laptop" role="tab" aria-selected="true" aria-controls="equipment-panel" data-explore="laptop">{icon('laptop')}<span><b>Business laptops</b><small>Work from anywhere</small></span><span aria-hidden="true">↗</span></button>
      <button id="tab-server" role="tab" aria-selected="false" aria-controls="equipment-panel" tabindex="-1" data-explore="server">{icon('server')}<span><b>Servers & storage</b><small>Build your foundation</small></span><span aria-hidden="true">↗</span></button>
      <button id="tab-network" role="tab" aria-selected="false" aria-controls="equipment-panel" tabindex="-1" data-explore="network">{icon('network')}<span><b>Networking equipment</b><small>Connect your workplace</small></span><span aria-hidden="true">↗</span></button></div>
      <div class="equipment-panel" id="equipment-panel" role="tabpanel" aria-labelledby="tab-laptop" tabindex="0">
      <div><span class="mini-label">Equipment explorer</span><h3 data-explorer-title>Business laptops</h3><p data-explorer-copy>Portable equipment for hybrid teams, business travel and everyday work. Start with the applications your team uses and the portability they need.</p><ul class="ticks" data-explorer-points><li>Match processor and memory to your applications</li><li>Consider battery, screen size and connectivity</li><li>Specify your quantity and preferred operating system</li></ul><div class="actions"><button class="btn" data-request="laptop" type="button">Request this solution ↗</button><button class="btn light" data-explorer-add="laptop" type="button">Add to enquiry +</button></div></div><div class="explorer-visual"><img data-explorer-photo src="{base}assets/photos/laptop.jpg" width="1100" height="730" loading="lazy" decoding="async" alt="Business laptop on a desk"></div></div>
      </div></div></section>'''
    needs=[('office','New office setup','Start a workplace from the ground up.','hardware'),('refresh','Equipment refresh','Plan what to replace and what to keep.','laptop'),('remote','Remote team','Equip people wherever they work.','network'),('infrastructure','Infrastructure upgrade','Review compute, storage and connectivity.','server')]
    usecases=f'''<section id="business-needs"><div class="wrap"><div class="section-head"><div>{eye('Start with the business need')}<h2>What are you planning next?</h2></div><p>You do not need a finished equipment specification to start a useful conversation.</p></div><div class="need-grid">'''+''.join(f'<a href="{base}request-quote/?need={key}" class="need-card">{icon(k)}<h3>{title}</h3><p>{copy}</p><span class="text-link">Plan this project ↗</span></a>' for key,title,copy,k in needs)+'</div></div></section>'
    photos=[('laptop','laptop','Business laptops','Portable equipment for teams on the move.','Business laptop; illustrative equipment photograph'),('desktop','desktop','Desktops & all-in-ones','Purpose-fit equipment for focused workplaces.','All-in-one desktop computer with a keyboard and mouse'),('server','servers','Servers & storage','Infrastructure shaped around your workloads.','Server racks; illustrative equipment photograph'),('network','network','Networking equipment','Connect users, devices and workplaces.','Ethernet cables connected to network patch-panel ports'),('printer','printer','Printers & office equipment','Discuss printing and everyday office needs.','Multifunction office printer and scanner'),('accessory','accessory','Peripherals & accessories','Complete the setup around your devices.','Wireless computer keyboard on a desk')]
    def equipment_cards(limit=6):
        return '<div class="equipment-grid">'+''.join(f'<article class="equipment-card">{photo(image,alt)}<div><h3>{title}</h3><p>{copy}</p>{add(key)}</div></article>' for i,(key,image,title,copy,alt) in enumerate(photos[:limit]))+'</div>'
    photo_section=f'<section class="pale"><div class="wrap"><div class="section-head"><div>{eye("Equipment, with purpose")}<h2>Equip the work ahead.</h2></div><a href="{base}solutions/" class="text-link">View all equipment categories ↗</a></div>{equipment_cards(3)}<p class="photo-note">Representative equipment photography via <a href="https://unsplash.com/license" target="_blank" rel="noopener noreferrer">Unsplash</a>. Models, specifications, availability and terms are confirmed in a quotation.</p></div></section>'
    timeline=f'''<section class="timeline-section" id="procurement-process"><div class="wrap"><div class="section-head"><div>{eye('A clear process')}<h2>Know what comes next.</h2></div><p>Select a stage to see what you can prepare and how the procurement conversation progresses.</p></div><div class="procurement-timeline" data-timeline>
      <div role="tablist" aria-label="Procurement stages" class="timeline-tabs">'''+''.join(f'<button type="button" role="tab" id="stage-{i}" aria-controls="stage-panel" aria-selected="{"true" if i==0 else "false"}" tabindex="{0 if i==0 else -1}" data-stage="{i}"><span>{i+1:02}</span>{title}</button>' for i,title in enumerate(['Define the brief','Review options','Consider the quote','Agree next steps']))+f'''</div><div class="stage-panel" id="stage-panel" role="tabpanel" aria-labelledby="stage-0" tabindex="0"><div><span class="mini-label" data-stage-label>01 / DEFINE THE BRIEF</span><h3 data-stage-title>Start with the work it needs to do.</h3><p data-stage-copy>Share equipment types, users, applications, quantities and the location. A clear business goal is a good starting point if the specification is still open.</p></div><div class="prepare-card"><span class="mini-label">WHAT TO PREPARE</span><ul class="ticks" data-stage-checks><li>Your equipment or service requirements</li><li>Estimated quantities and delivery region</li><li>Preferred timing and optional budget guidance</li></ul><a class="text-link" href="{base}request-quote/">Start your enquiry ↗</a></div></div></div></div></section>'''
    comparison=f'''<section class="compare-section pale" id="equipment-comparison"><div class="wrap"><div class="section-head"><div>{eye('Choose with confidence')}<h2>Which setup fits your team?</h2></div><p>Compare equipment types by how they are used. Final suitability depends on your applications, specifications and operating environment.</p></div>
      <fieldset class="compare-picker"><legend>Select two or three equipment types</legend><label><input type="checkbox" data-compare="laptop" checked> Business laptop</label><label><input type="checkbox" data-compare="desktop" checked> Desktop / all-in-one</label><label><input type="checkbox" data-compare="workstation" checked> Workstation</label></fieldset><div class="compare-table" tabindex="0" role="region" aria-label="Equipment comparison"><table><caption class="sr-only">Equipment suitability comparison</caption><thead><tr><th scope="col">Consideration</th><th scope="col" data-compare-col="laptop">Business laptop</th><th scope="col" data-compare-col="desktop">Desktop / all-in-one</th><th scope="col" data-compare-col="workstation">Workstation</th></tr></thead><tbody>'''+''.join('<tr><th scope="row">'+label+'</th>'+''.join(f'<td data-compare-col="{k}">{value}</td>' for k,value in zip(['laptop','desktop','workstation'],values))+'</tr>' for label,values in [('Best suited to',['Hybrid work, travel and everyday business tasks','Fixed desks and general office workloads','Demanding design, engineering or specialist workloads']),('Portability',['Designed to move between workplaces','Usually stays at a fixed desk','Depends on whether a mobile or tower model is chosen']),('Upgrade considerations',['Model-dependent memory and storage options','Tower models often offer more upgrade flexibility','Expansion, graphics and memory depend on the model']),('What to specify',['Screen size, battery needs, applications and ports','Desk space, monitors, applications and connectivity','Application requirements, graphics, memory and storage'])])+f'''<tr><th scope="row">Your next step</th><td data-compare-col="laptop">{add('laptop')}</td><td data-compare-col="desktop">{add('desktop')}</td><td data-compare-col="workstation">{add('workstation')}</td></tr></tbody></table></div><p class="compare-feedback" role="status"></p><a class="text-link" href="{base}request-quote/?category=consulting">Not sure? Request specification advice ↗</a></div></section>'''
    # The hero and equal service overview are supplied by the shared brand template.
    pages['']=(pages[''][0],pages[''][1]+usecases+explorer+photo_section+timeline+cta())
    service_solutions=[
      ('consulting','consulting','Technology & IT consulting','Review technology priorities, specifications and the way your systems support your business.','A team planning a project with laptops and a shared workflow board'),
      ('procurement','laptop','Procurement & equipment supply','Discuss sourcing, importation, exportation, wholesale or retail supply of computer hardware, accessories and peripherals.','Business laptop illustrating the equipment specification for a procurement enquiry'),
      ('support','support','Installation, maintenance & support','Plan computer labs, equipment installation, commissioning and ongoing technical support around your users and site.','A technician installing a computer memory module'),
    ]
    service_solutions_section='<section class="pale" id="it-service-solutions"><div class="wrap"><div class="section-head"><div>'+eye('EXPERTISE THROUGH THE TECHNOLOGY LIFECYCLE')+'<h2>Plan it. Source it.<br>Keep it working.</h2></div><p>From technology decisions to equipment supply and ongoing support, discuss the services your project needs.</p></div><div class="service-solutions-grid">'+''.join(f'<article class="equipment-card">{photo(image,alt)}<div><h3>{title}</h3><p>{copy}</p><a class="text-link" href="{base}request-quote/?category={key}">Discuss this solution ↗</a></div></article>' for i,(key,image,title,copy,alt) in enumerate(service_solutions))+'</div></div></section>'
    solutions_nav='<div class="solutions-jump"><div class="wrap"><nav aria-label="Solution categories"><a href="#digital-solutions">Improve a workflow</a><a href="#it-service-solutions">Plan & support IT</a><a href="#hardware-solutions">Equip a workplace</a></nav></div></div>'
    equipment_section=f'<section id="hardware-solutions"><div class="wrap"><div class="section-head"><div>{eye("HARDWARE FOR YOUR WORKPLACE")}<h2>Equip every part<br>of your business.</h2></div><p>Explore equipment, add what you need to your enquiry list and compare suitable workplace options.</p></div>{equipment_cards()}<p class="notice" style="margin-top:25px">These are enquiry categories, not a live stock catalogue. Models, prices, availability, warranties and delivery terms are confirmed in your quotation.</p></div></section>'
    image_note='<div class="wrap"><p class="photo-note solution-photo-note">Images illustrate each solution and are sourced from <a href="https://unsplash.com/license" target="_blank" rel="noopener noreferrer">Unsplash</a>. They do not depict Lutera stock, premises, staff or completed projects.</p></div>'
    pages['solutions']=('IT, AI & Business Solutions',pagehero('What does your<br>organisation need next?','Explore AI and automation, software development, data analytics, cloud and systems integration, technology consulting, equipment supply and technical support.','IT, AI & hardware solutions','Solutions')+solutions_nav+digital_services(base)+service_solutions_section+equipment_section+image_note+comparison+usecases+cta())
    # Reuse the interactive timeline on the procurement service page.
    title,content=pages['services/it-procurement'];pages['services/it-procurement']=(title,content.replace(cta(),timeline+cta()))
    # Guided form stays a regular HTML POST when JavaScript is unavailable.
    def field(name,label,typ='text',required=False,attrs=''):
        return f'<div class="field"><label for="{name}">{label}{" *" if required else " <small>(optional)</small>"}</label><input id="{name}" name="{name}" type="{typ}" {"required" if required else ""} {attrs}></div>'
    quote=pagehero('A clearer brief.<br>A better next step.','Tell us about your AI, software, IT service or equipment project in three short steps. Review your requirements and send one organized enquiry.','Request a quote','Request a quote')
    quote+=f'''<section class="guided-section"><div class="wrap guided-layout"><div><ol class="wizard-progress" aria-label="Quote request progress"><li aria-current="step"><span>01</span>Your needs</li><li><span>02</span>Specifications</li><li><span>03</span>Contact & review</li></ol><div id="wizard-status" class="notice" role="status" tabindex="-1"></div>
    <form id="rfq-form" class="guided-form form-box" action="https://formsubmit.co/chimaster010@gmail.com" method="POST">
    <input type="hidden" name="_subject" value="LUTERA | New procurement / quote request"><input type="hidden" name="_template" value="table"><input type="hidden" name="_next" value="{origin}{base}thank-you/"><input type="hidden" name="equipment_list" id="equipment-list-payload"><input type="hidden" name="enquiry_summary" id="enquiry-summary-payload">
    <fieldset class="quote-step" data-quote-step="0"><legend>Your needs</legend><p class="step-description">Start with your goal. You can refine the exact specifications with us.</p><div class="form-grid">
    <div class="field full"><label for="service_category">What can we help with? *</label><select id="service_category" name="service_category" required><option value="">Select a service</option><option value="procurement">IT procurement & sourcing</option><option value="hardware">Computer hardware & equipment</option><option value="consulting">IT consulting</option><option value="support">Technical support</option><option value="ai">AI solutions, agents &amp; automation</option><option value="software">Software design &amp; development</option><option value="data">Data analytics</option><option value="cloud">Cloud solutions &amp; systems integration</option><option value="other">Other enquiry</option></select></div>
    <div class="field full"><label for="project_type">What are you planning? <small>(optional)</small></label><select id="project_type" name="project_type"><option value="">Choose a business need</option>'''+''.join(f'<option value="{key}">{title}</option>' for key,title,_,_ in needs)+'''<option value="other">Another project</option></select></div>
    <div class="field full quote-list-slot"><div class="list-heading"><h3>Your equipment list</h3><button class="text-button" type="button" data-open-enquiry>Edit list</button></div><div data-quote-list><p>No equipment selected yet. You can describe your requirements below.</p></div></div>
    <div class="field full"><label for="requirements">What does your organization need? *</label><textarea id="requirements" name="requirements" required minlength="20" maxlength="5000" placeholder="Tell us about the equipment, applications, users or service requirements."></textarea></div></div></fieldset>
    <fieldset class="quote-step" data-quote-step="1"><legend>Specifications & timing</legend><p class="step-description">Include what you know. Budget is optional.</p><div class="form-grid">'''+field('quantity','Total equipment quantity','number',False,'min="1" max="8000000" step="1"')+field('budget_range','Budget range','text',False,'maxlength="120" placeholder="Include currency, if known"')+field('delivery_city_or_region','Delivery city or region','text',False,'maxlength="160"')+field('needed_by','Preferred date','date')+'''<div class="field full"><label for="additional_notes">Additional specifications or notes <small>(optional)</small></label><textarea id="additional_notes" name="additional_notes" maxlength="2000" placeholder="For example: operating system, compatibility, preferred screen sizes or existing infrastructure."></textarea></div></div></fieldset>
    <fieldset class="quote-step" data-quote-step="2"><legend>Contact & review</legend><p class="step-description">Check your brief and tell us how to reach you.</p><div class="form-grid">'''+field('organization_name','Organization name',required=True,attrs='maxlength="160" autocomplete="organization"')+field('contact_name','Contact name',required=True,attrs='maxlength="120" autocomplete="name"')+field('email','Work email','email',True,'maxlength="254" autocomplete="email"')+field('phone_or_whatsapp','Phone / WhatsApp','tel',False,'maxlength="40" autocomplete="tel"')+f'''<div class="field full"><details class="quote-review" open><summary>Your enquiry summary</summary><div data-review-summary></div></details></div><div class="field full"><label class="check"><input type="checkbox" name="privacy_acknowledged" required><span>I have read the <a href="{base}privacy/">privacy notice</a> and acknowledge processing of my details to respond to this enquiry. *</span></label></div></div></fieldset>
    <div class="honey" aria-hidden="true"><label for="website">Leave empty</label><input id="website" name="_honey" tabindex="-1" autocomplete="off"></div>
    <div class="wizard-actions"><button class="btn light" type="button" data-wizard-back hidden>Back</button><button class="btn" type="button" data-wizard-next hidden>Continue ↗</button><button class="btn" type="submit" id="rfq-submit">Submit quote request ↗</button></div><p class="form-footnote">Your enquiry is routed to chimaster010@gmail.com via FormSubmit. Complete any spam-prevention check shown after sending. An enquiry does not place an order or guarantee supply.</p></form></div>
    <aside class="quote-aside"><div class="quote-aside-card"><span class="mini-label">FROM YOUR BRIEF TO A PLAN</span><h3>Every good project starts with the right questions.</h3><ul class="ticks"><li>Describe your project goals and requirements</li><li>Include quantities and location</li><li>Share your preferred timing</li><li>Keep budget guidance optional</li></ul></div><div class="quote-aside-contact"><p>Prefer to talk it through?</p><a href="https://wa.me/2349026276130" target="_blank" rel="noopener noreferrer" class="text-link">Chat on WhatsApp ↗</a><a href="mailto:chimaster010@gmail.com">chimaster010@gmail.com</a></div></aside></div></section>'''
    pages['request-quote']=('Request a Quote',quote)
    # Notices reflect the functional, tab-scoped list; personal/contact form data is not saved.
    for route in ['privacy','cookies']:
        title,body=pages[route]
        body=body.replace('The public pages do not store enquiry details in browser storage.', 'The equipment enquiry list and selected business need are kept in session storage for the current browser tab. Contact details and free-text form answers are not saved in browser storage. You can clear the equipment list at any time; closing the tab clears the saved session.')
        body=body.replace('The public pages do not set advertising or analytics cookies and do not store enquiry details in browser local storage.', 'The public pages do not set advertising or analytics cookies. Functional session storage keeps your selected equipment and business need across pages in the current browser tab. Contact details and free-text answers are not saved. You can clear the list yourself; closing the tab clears the saved session.')
        pages[route]=(title,body)
    return pages

def chrome(base):
    return f'''<div class="site-announcer sr-only" id="site-announcer" role="status" aria-live="polite"></div>
    <dialog id="enquiry-dialog" class="enquiry-dialog" aria-labelledby="enquiry-title"><div class="drawer-head"><div><span class="mini-label">YOUR PROCUREMENT BRIEF</span><h2 id="enquiry-title">Your enquiry list</h2></div><button type="button" class="icon-button" data-close-enquiry aria-label="Close enquiry list">×</button></div><p class="drawer-intro">Gather the equipment you need, set quantities and send one clear request. Specifications and supply terms are confirmed through a quotation.</p><div id="enquiry-items"></div><p id="enquiry-list-note" class="form-footnote"></p><div class="drawer-actions"><button class="text-button" data-clear-enquiry type="button">Clear list</button><button class="text-button" data-copy-enquiry type="button">Copy list</button></div><a class="btn" data-continue-quote href="{base}request-quote/">Continue to quote ↗</a><a class="text-link" href="{base}solutions/">Explore more equipment ↗</a></dialog>
    <div class="enquiry-toast" role="status" hidden><span data-toast-text></span><button type="button" data-open-enquiry>View list ↗</button></div>
    <details class="floating-contact">
    <summary class="floating-contact-toggle"><span class="sr-only">Contact options</span><svg class="contact-chat-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M21 11.5a8.5 8.5 0 0 1-8.5 8.5H4l-2 2V11.5a9.5 9.5 0 0 1 19 0Z"/><path d="M7 11h10M7 15h6"/></svg><svg class="contact-close-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" aria-hidden="true"><path d="m6 6 12 12M18 6 6 18"/></svg></summary>
    <nav class="floating-contact-options" aria-label="Quick contact">
    <a href="{base}request-quote/" class="floating-quote-link"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M14 2H5v20h14V7l-5-5Z"/><path d="M14 2v6h5M8 12h8M8 16h6"/></svg><span>Request a quote</span><span data-enquiry-count>0</span></a>
    <a href="https://wa.me/2349026276130" target="_blank" rel="noopener noreferrer" class="floating-whatsapp-link"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20.5 11.5a9 9 0 0 1-13.2 8L2 21l1.5-5.3a9 9 0 1 1 17-4.2Z"/><path d="m8 7-1 2c1 4 3 6 7 7l2-1-2-3-2 1-2-2 1-2-3-2Z"/></svg><span>WhatsApp chat</span><span aria-hidden="true">↗</span></a>
    </nav></details>'''
